 public int scan(String c){schedule(c);if(messaging()!=null){int count=0;for(Long id:db.queryForList("SELECT id FROM channel_product_pull WHERE company_code=? AND state IN ('PENDING','RUNNING') AND next_attempt<=NOW() ORDER BY id LIMIT 10",Long.class,c)){wake(c,id);count++;}matchWake(c,null);return count;}long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(40);int count=0;for(Long id:db.queryForList("SELECT id FROM channel_product_pull WHERE company_code=? AND state IN ('PENDING','RUNNING') AND next_attempt<=NOW() AND (lease_until IS NULL OR lease_until<NOW()) ORDER BY id LIMIT 10",Long.class,c)){if(System.nanoTime()>deadline)break;process(c,id);count++;}autoBind(c,null);return count;}
 void enqueueMissing(String c,long channel,List<String> missing){tx().execute(status->{db.queryForList("SELECT channel_id FROM t_channel WHERE UPPER(company_code)=UPPER(?) AND channel_id=? FOR UPDATE",c,channel);List<Long> active=db.queryForList("SELECT id FROM channel_product_pull WHERE company_code=? AND channel_id=? AND (state IN ('PENDING','RUNNING') OR (state IN ('FAILED','PARTIAL') AND attempts<3)) ORDER BY id DESC LIMIT 1 FOR UPDATE",Long.class,c,channel);long task;if(active.isEmpty()){task=n(pull(c,channel,map("mode","IDS","item_ids",missing.subList(0,Math.min(100,missing.size()))),"订单商品补拉"),"id");db.update("UPDATE channel_product_pull SET trigger_source='BUSINESS' WHERE company_code=? AND id=?",c,task);}else task=active.get(0);for(String id:missing)db.update("INSERT IGNORE INTO channel_product_pull_item(company_code,task_id,item_id) VALUES (?,?,?)",c,task,id);wake(c,task);return null;});}
 void schedule(String c){
  db.update("INSERT IGNORE INTO channel_product_policy(company_code,channel_id) SELECT ?,c.channel_id FROM t_channel c JOIN channel_platform_binding b ON UPPER(b.company_code)=UPPER(c.company_code) AND b.channel_id=c.channel_id WHERE UPPER(c.company_code)=UPPER(?) AND c.channel_type='TM' AND c.enabled=1 AND c.to_channel_enabled=1 AND b.auth_status='AUTHORIZED' AND b.token_expires_at>NOW()",c,c);
  for(Map<String,Object> p:db.queryForList("SELECT p.* FROM channel_product_policy p JOIN t_channel c ON UPPER(c.company_code)=UPPER(p.company_code) AND c.channel_id=p.channel_id JOIN channel_platform_binding b ON UPPER(b.company_code)=UPPER(c.company_code) AND b.channel_id=c.channel_id WHERE p.company_code=? AND p.auto_pull=1 AND p.next_run_at<=NOW() AND c.enabled=1 AND c.to_channel_enabled=1 AND b.auth_status='AUTHORIZED' AND b.token_expires_at>NOW() ORDER BY p.next_run_at LIMIT 5",c)){
   long channel=n(p,"channel_id");try{tx().execute(status->{db.queryForList("SELECT channel_id FROM t_channel WHERE UPPER(company_code)=UPPER(?) AND channel_id=? FOR UPDATE",c,channel);if(db.update("UPDATE channel_product_policy SET next_run_at=DATE_ADD(NOW(),INTERVAL interval_minutes MINUTE),last_attempt_at=NOW() WHERE company_code=? AND channel_id=? AND auto_pull=1 AND next_run_at<=NOW()",c,channel)==0)return null;if(db.queryForObject("SELECT COUNT(*) FROM channel_product_pull WHERE company_code=? AND channel_id=? AND state IN ('PENDING','RUNNING')",Long.class,c,channel)==0){long id=n(pull(c,channel,map("mode","ALL"),"商品自动同步"),"id");db.update("UPDATE channel_product_pull SET trigger_source='SCHEDULER' WHERE company_code=? AND id=?",c,id);}return null;});}catch(RuntimeException e){db.update("UPDATE channel_product_policy SET last_error=?,next_run_at=DATE_ADD(NOW(),INTERVAL 5 MINUTE) WHERE company_code=? AND channel_id=?",error(e),c,channel);}
  }
  for(Map<String,Object> t:db.queryForList("SELECT t.id FROM channel_product_pull t JOIN channel_product_policy p ON p.company_code=t.company_code AND p.channel_id=t.channel_id WHERE t.company_code=? AND p.auto_pull=1 AND t.state IN ('FAILED','PARTIAL') AND t.attempts<3 AND t.next_attempt<=NOW() AND NOT EXISTS(SELECT 1 FROM channel_product_pull a WHERE a.company_code=t.company_code AND a.channel_id=t.channel_id AND a.state IN ('PENDING','RUNNING')) ORDER BY t.id LIMIT 5",c))try{retry(c,n(t,"id"));}catch(RuntimeException ignored){}
 }
 static String code(String value){int start=0,end=value.length();while(start<end&&(Character.isWhitespace(value.charAt(start))||Character.isSpaceChar(value.charAt(start))))start++;while(end>start&&(Character.isWhitespace(value.charAt(end-1))||Character.isSpaceChar(value.charAt(end-1))))end--;return value.substring(start,end);}
 public int autoBind(String c,Long channel){List<Object> args=new ArrayList<>(Collections.singletonList(c));String where="";if(channel!=null){where=" AND p.channel_id=?";args.add(channel);}List<Map<String,Object>> pending=db.queryForList("SELECT p.* FROM channel_platform_product p JOIN channel_product_policy r ON r.company_code=p.company_code AND r.channel_id=p.channel_id JOIN t_channel c ON UPPER(c.company_code)=UPPER(p.company_code) AND c.channel_id=p.channel_id JOIN channel_platform_binding b ON UPPER(b.company_code)=UPPER(p.company_code) AND b.channel_id=p.channel_id AND b.expected_shop_id=p.platform_shop_id WHERE p.company_code=? AND p.present=1 AND p.binding_state='UNBOUND' AND p.auto_bind_allowed=1 AND p.oms_sku_sn IS NULL AND p.next_match_at<=NOW() AND r.auto_bind=1 AND (p.match_issue='' OR r.rematch_enabled=1) AND c.enabled=1 AND c.to_channel_enabled=1"+where+" ORDER BY p.next_match_at,p.id LIMIT 50",args.toArray());if(pending.isEmpty())return 0;
  List<String> codes=new ArrayList<>();for(Map<String,Object> p:pending){String code=code(s(p,"outer_id"));if(!code.isEmpty()&&!codes.contains(code))codes.add(code);}List<Map<String,Object>> matches;try{matches=codes.isEmpty()?Collections.emptyList():StockSyncService.data(goods.goods(c,codes,SecurityConstants.INNER));require(matches!=null,"OMS商品服务没有返回匹配结果");}catch(RuntimeException e){for(Map<String,Object> p:pending)db.update("UPDATE channel_platform_product SET match_issue='OMS商品服务暂不可用，稍后自动重试',next_match_at=DATE_ADD(NOW(),INTERVAL 1 MINUTE) WHERE company_code=? AND id=? AND binding_revision=? AND binding_state='UNBOUND' AND auto_bind_allowed=1",c,p.get("id"),p.get("binding_revision"));return 0;}Map<String,List<Map<String,Object>>> found=new HashMap<>();for(Map<String,Object> g:matches)found.computeIfAbsent(s(g,"sku_sn"),k->new ArrayList<>()).add(g);int count=0;
  for(Map<String,Object> p:pending){String code=code(s(p,"outer_id"));List<Map<String,Object>> target=found.getOrDefault(code,Collections.emptyList());String issue=code.isEmpty()?"平台商家编码缺失":target.isEmpty()?"商家编码未匹配到OMS SKU":target.size()!=1?"商家编码匹配到多个OMS SKU":"";
   boolean bound=tx().execute(status->{Map<String,Object> current=product(c,n(p,"id"),true);if(n(current,"binding_revision")!=n(p,"binding_revision")||!"UNBOUND".equals(s(current,"binding_state"))||n(current,"auto_bind_allowed")!=1||n(current,"present")!=1||n(settings.products(c,n(p,"channel_id")),"auto_bind")!=1)return false;if(!issue.isEmpty()){db.update("UPDATE channel_platform_product SET match_issue=?,next_match_at=DATE_ADD(NOW(),INTERVAL 5 MINUTE) WHERE company_code=? AND id=?",issue,c,p.get("id"));return false;}Map<String,Object> g=target.get(0);long revision=n(p,"binding_revision")+1;String reason="商家编码精确匹配OMS SKU："+code;db.update("UPDATE channel_platform_product SET binding_state='BOUND',oms_sku_sn=?,oms_goods_name=?,goods_type=?,binding_revision=?,binding_source='AUTO',binding_reason=?,bound_by='系统自动绑定',bound_at=NOW(),match_issue='' WHERE company_code=? AND id=?",code,s(g,"goods_name"),type(g),revision,reason,c,p.get("id"));event(c,n(p,"id"),"AUTO_BIND","",code,revision,reason,"系统自动绑定",product(c,n(p,"id"),false));return true;});if(bound)count++;
  }return count;
 }

 public Map<String,Object> items(String c,Long channel,String keyword,String state,String listing,int page,int size){require(page>0&&page<=100000&&size>0&&size<=100&&keyword.length()<=128,"查询范围无效");List<Object> args=new ArrayList<>(Collections.singletonList(c));String where=" WHERE i.company_code=?";if(channel!=null){where+=" AND i.channel_id=?";args.add(channel);}if(!listing.isEmpty()){require(Arrays.asList("onsale","instock","unknown").contains(listing),"上下架状态无效");where+=" AND i.listing_state=?";args.add(listing);}if(!keyword.trim().isEmpty()){where+=" AND (i.item_id=? OR i.title LIKE ? OR EXISTS(SELECT 1 FROM channel_platform_product p WHERE p.company_code=i.company_code AND p.channel_id=i.channel_id AND p.item_id=i.item_id AND (p.sku_id=? OR p.outer_id=? OR p.oms_sku_sn=?)))";args.add(keyword.trim());args.add("%"+keyword.trim().replace("%","\\%").replace("_","\\_")+"%");for(int a=0;a<3;a++)args.add(keyword.trim());}if(!state.isEmpty()){require(Arrays.asList("BOUND","UNBOUND","REVIEW","IGNORED","REMOVED","PARTIAL").contains(state),"绑定筛选无效");if(state.equals("REMOVED"))where+=" AND NOT EXISTS(SELECT 1 FROM channel_platform_product p WHERE p.company_code=i.company_code AND p.channel_id=i.channel_id AND p.item_id=i.item_id AND p.present=1)";else if(state.equals("BOUND"))where+=" AND EXISTS(SELECT 1 FROM channel_platform_product p WHERE p.company_code=i.company_code AND p.channel_id=i.channel_id AND p.item_id=i.item_id AND p.present=1) AND NOT EXISTS(SELECT 1 FROM channel_platform_product p WHERE p.company_code=i.company_code AND p.channel_id=i.channel_id AND p.item_id=i.item_id AND p.present=1 AND p.binding_state<>'BOUND')";else if(state.equals("PARTIAL"))where+=" AND EXISTS(SELECT 1 FROM channel_platform_product p WHERE p.company_code=i.company_code AND p.channel_id=i.channel_id AND p.item_id=i.item_id AND p.present=1 AND p.binding_state='BOUND') AND EXISTS(SELECT 1 FROM channel_platform_product p WHERE p.company_code=i.company_code AND p.channel_id=i.channel_id AND p.item_id=i.item_id AND p.present=1 AND p.binding_state<>'BOUND')";else{where+=" AND EXISTS(SELECT 1 FROM channel_platform_product p WHERE p.company_code=i.company_code AND p.channel_id=i.channel_id AND p.item_id=i.item_id AND p.present=1 AND p.binding_state=?)";args.add(state);}}
  long total=db.queryForObject("SELECT COUNT(*) FROM channel_platform_item i"+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);List<Map<String,Object>> rows=db.queryForList("SELECT i.*,c.channel_name FROM channel_platform_item i JOIN t_channel c ON UPPER(c.company_code)=UPPER(i.company_code) AND c.channel_id=i.channel_id"+where+" ORDER BY i.id DESC LIMIT ? OFFSET ?",args.toArray());rows.forEach(StockSyncService::dates);
  if(!rows.isEmpty()){List<Object> values=new ArrayList<>(Collections.singletonList(c));StringJoiner ids=new StringJoiner(" OR ","(",")");for(Map<String,Object> row:rows){ids.add("(channel_id=? AND item_id=?)");values.add(row.get("channel_id"));values.add(row.get("item_id"));}List<Map<String,Object>> stats=db.queryForList("SELECT channel_id,item_id,COUNT(*) spec_count,SUM(present=1) sku_count,SUM(present=1 AND binding_state='BOUND') bound_count,SUM(present=1 AND binding_state='REVIEW') review_count FROM channel_platform_product WHERE company_code=? AND "+ids+" GROUP BY channel_id,item_id",values.toArray());for(Map<String,Object> row:rows){row.put("skus",new ArrayList<>());row.putAll(map("spec_count",0,"sku_count",0,"bound_count",0,"review_count",0));for(Map<String,Object> stat:stats)if(n(stat,"channel_id")==n(row,"channel_id")&&s(stat,"item_id").equals(s(row,"item_id")))row.putAll(stat);}}

  return map("rows",rows,"total",total);
 }
